from moler.cmd.commandtextualgeneric import CommandTextualGeneric
from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import ParsingDone


class Trmsg(GenericUnixCommand):
    """Trmsg command class."""

    def __init__(self, connection, prompt=None, expected_prompt=r'trmsg#',
                 newline_chars=None, runner=None, target_newline="\n"):
        """
        Trmsg command.

        :param connection:.
        :param prompt: Prompt of the starting shell
        :param expected_prompt: Prompt of the target shell reached after exit command
        :param newline_chars:
        """
        super(Trmsg, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.ret_required = False
        self.target_newline = target_newline

        # Parameters defined by calling the command
        self._re_expected_prompt = CommandTextualGeneric._calculate_prompt(expected_prompt)  # Expected prompt on device

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "trmsg"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        try:
            self._is_target_prompt(line)
        except ParsingDone:
            pass  # line has been fully parsed by one of above parse-methods

    def _is_target_prompt(self, line):
        if self._regex_helper.search_compiled(self._re_expected_prompt, line):
            if not self.done():
                self.set_result({})
                raise ParsingDone


COMMAND_OUTPUT = """
[root@FCPU-0(909514) /root]
# trmsg
trmsg#"""

COMMAND_KWARGS = {
    "expected_prompt": r'trmsg#'
}

COMMAND_RESULT = {}
